//! A codec module's functions (SINCE videocodec 1.4): what
//! videocodec.library calls a decoder of pictures in LIBS:codecs/ with,
//! after a module's tag in its file said it decodes the track's codec.
//! Every module has them (sdk/libs/videocodec/vcodec.zig); the base is
//! the module's, opened with OpenLibrary("codecs/<file>"). One task calls
//! a decoder at a time - the one that decodes the film's pictures.
//!
//! Generated by sdk/tools/fd2zig from sdk/fd/vcodec_lib.fd: change that file
//! and run `zig build fd`, not this one.

const libraries = @import("../libs/exec/libraries.zig");
const videocodec = @import("../libs/videocodec/videocodec.zig");
const vcodec = @import("../libs/videocodec/vcodec.zig");

/// The name to open it by (OpenLibrary, OpenDevice).
pub const NAME = "vcodec";

/// Each function's offset in the jump table (its LVO).
pub const LVO = struct {
    pub const GetVCodecInfo = libraries.lvo(4);
    pub const OpenVCodec = libraries.lvo(5);
    pub const CloseVCodec = libraries.lvo(6);
    pub const SendVCodecPacket = libraries.lvo(7);
    pub const ReceiveVCodecFrame = libraries.lvo(8);
    pub const ReleaseVCodecFrame = libraries.lvo(9);
    pub const FlushVCodec = libraries.lvo(10);
};

/// Each function's type, by its name in LVO. The first argument is the
/// library's base.
pub const Fn = struct {
    pub const GetVCodecInfo = *const fn (*VCodecBase, *vcodec.VCodecDecoder, *vcodec.VCodecInfo) callconv(.c) i32;
    pub const OpenVCodec = *const fn (*VCodecBase, *const vcodec.VCodecParams, ?*i32) callconv(.c) ?*vcodec.VCodecDecoder;
    pub const CloseVCodec = *const fn (*VCodecBase, ?*vcodec.VCodecDecoder) callconv(.c) void;
    pub const SendVCodecPacket = *const fn (*VCodecBase, *vcodec.VCodecDecoder, *const vcodec.VCodecPacket) callconv(.c) i32;
    pub const ReceiveVCodecFrame = *const fn (*VCodecBase, *vcodec.VCodecDecoder, *videocodec.VideoFrame) callconv(.c) i32;
    pub const ReleaseVCodecFrame = *const fn (*VCodecBase, *vcodec.VCodecDecoder, *videocodec.VideoFrame) callconv(.c) void;
    pub const FlushVCodec = *const fn (*VCodecBase, *vcodec.VCodecDecoder) callconv(.c) void;
};

/// The library's base. Its methods are the library's functions, and
/// each calls through the jump table.
pub const VCodecBase = opaque {
    /// The Library header at the base.
    pub fn lib(self: *VCodecBase) *libraries.Library {
        return @ptrCast(@alignCast(self));
    }

    /// What the decoder read from the stream, into `info`: 0, or
    /// VCERR_NEED_DATA while it has read nothing to say it from. The size is
    /// the pictures' as they are shown, cropped; the rate 0 / 0 when the
    /// stream does not say it. A task will do; it does not wait.
    pub fn GetVCodecInfo(self: *VCodecBase, decoder: *vcodec.VCodecDecoder, info: *vcodec.VCodecInfo) i32 {
        return libraries.call(self, LVO.GetVCodecInfo, Fn.GetVCodecInfo, .{ decoder, info });
    }

    /// A decoder for a track, or null and why in `err`: VCERR_NOCODEC when
    /// this module cannot decode it here - the board has not its chip, or the
    /// codec is not one of its own - VCERR_BUSY when its chip runs no more,
    /// VCERR_UNSUPPORTED, VCERR_CORRUPT for a setup it cannot read,
    /// VCERR_NOMEMORY. `params` and what it points at are the caller's for
    /// the call alone. On a process: a chip's decoder may load its firmware.
    pub fn OpenVCodec(self: *VCodecBase, params: *const vcodec.VCodecParams, err: ?*i32) ?*vcodec.VCodecDecoder {
        return libraries.call(self, LVO.OpenVCodec, Fn.OpenVCodec, .{ params, err });
    }

    /// The decoder closed, its memory freed - and the frames it still has
    /// lent, which may not be shown after.
    pub fn CloseVCodec(self: *VCodecBase, decoder: ?*vcodec.VCodecDecoder) void {
        return libraries.call(self, LVO.CloseVCodec, Fn.CloseVCodec, .{decoder});
    }

    /// A packet of the track in, or its end (VCPKT_END): 0, or VCERR_FULL
    /// when it has no room for it yet - a frame is to be taken
    /// (ReceiveVCodecFrame) and the packet sent again - or VCERR_NOMEMORY,
    /// VCERR_CORRUPT. The bytes are the caller's for the call alone: the
    /// decoder copies what it keeps. A packet marked VCPKT_DROP is due before
    /// what is shown, and may be decoded only as far as later pictures need
    /// it.
    pub fn SendVCodecPacket(self: *VCodecBase, decoder: *vcodec.VCodecDecoder, packet: *const vcodec.VCodecPacket) i32 {
        return libraries.call(self, LVO.SendVCodecPacket, Fn.SendVCodecPacket, .{ decoder, packet });
    }

    /// The next frame in the order frames are shown, into `frame`: 0;
    /// VCERR_NEED_DATA when the decoder wants a packet first; VCERR_END after
    /// the last frame, once the end was sent; VCERR_UNSUPPORTED for a stream
    /// it turns out it cannot decode - before its first frame, the next
    /// module is given the track; VCERR_CORRUPT for a picture it stopped on,
    /// which it is called again after; VCERR_BUSY with `held` frames lent;
    /// VCERR_NOMEMORY. The frame's planes are the decoder's, lent until
    /// ReleaseVCodecFrame, its `time` the packet's that made it, its
    /// `private` the decoder's.
    pub fn ReceiveVCodecFrame(self: *VCodecBase, decoder: *vcodec.VCodecDecoder, frame: *videocodec.VideoFrame) i32 {
        return libraries.call(self, LVO.ReceiveVCodecFrame, Fn.ReceiveVCodecFrame, .{ decoder, frame });
    }

    /// A frame the decoder lent given back, as ReceiveVCodecFrame filled it
    /// in; frames come back in any order.
    pub fn ReleaseVCodecFrame(self: *VCodecBase, decoder: *vcodec.VCodecDecoder, frame: *videocodec.VideoFrame) void {
        return libraries.call(self, LVO.ReleaseVCodecFrame, Fn.ReleaseVCodecFrame, .{ decoder, frame });
    }

    /// Everything sent and not yet handed out forgotten, for a seek: the
    /// next packet is a key packet, and the frames lent stay lent.
    pub fn FlushVCodec(self: *VCodecBase, decoder: *vcodec.VCodecDecoder) void {
        return libraries.call(self, LVO.FlushVCodec, Fn.FlushVCodec, .{decoder});
    }
};
